def solve(grid):
    if not grid:return 0
    g=[list(r) for r in grid]; R=len(g); C=len(g[0]); count=0
    for i in range(R):
     for j in range(C):
      if g[i][j] in (1,"1"):
       count+=1; stack=[(i,j)]; g[i][j]=0
       while stack:
        x,y=stack.pop()
        for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
         if 0<=a<R and 0<=b<C and g[a][b] in (1,"1"): g[a][b]=0; stack.append((a,b))
    return count

def solve(num_courses, prerequisites):
    graph=[[] for _ in range(num_courses)]; indeg=[0]*num_courses
    for a,b in prerequisites: graph[b].append(a); indeg[a]+=1
    q=[i for i,v in enumerate(indeg) if v==0]; seen=0
    while q:
      u=q.pop(); seen+=1
      for v in graph[u]:
       indeg[v]-=1
       if indeg[v]==0:q.append(v)
    return seen==num_courses

