from collections import deque
def solve(grid):
    n=len(grid)
    if not n or grid[0][0] or grid[n-1][n-1]: return -1
    q=deque([(0,0,1)]); seen={(0,0)}
    while q:
      r,c,d=q.popleft()
      if (r,c)==(n-1,n-1):return d
      for dr in (-1,0,1):
       for dc in (-1,0,1):
        nr,nc=r+dr,c+dc
        if 0<=nr<n and 0<=nc<n and not grid[nr][nc] and (nr,nc) not in seen:
         seen.add((nr,nc));q.append((nr,nc,d+1))
    return -1

def solve(board,word):
    if not word:return True
    R=len(board); C=len(board[0]) if R else 0
    def dfs(i,j,k):
      if k==len(word):return True
      if not(0<=i<R and 0<=j<C) or board[i][j]!=word[k]:return False
      ch=board[i][j]; board[i][j]=None
      ok=any(dfs(i+di,j+dj,k+1) for di,dj in ((1,0),(-1,0),(0,1),(0,-1)))
      board[i][j]=ch; return ok
    return any(dfs(i,j,0) for i in range(R) for j in range(C))

def solve(operations, capacity):
    cache=[]; out=[]
    for op,key,value in operations:
      if op=="put":
       if key in [x[0] for x in cache]: cache=[x for x in cache if x[0]!=key]
       cache.append((key,value))
       if len(cache)>capacity:cache.pop(0)
       out.append(None)
      elif op=="get":
       idx=next((i for i,x in enumerate(cache) if x[0]==key),None)
       if idx is None:out.append(-1)
       else:
        item=cache.pop(idx);cache.append(item);out.append(item[1])
    return out

